   [158]={next_id=159, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蒂雅站在原地，手里的盘子微微倾斜，汤差点洒出来。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT301_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4509", 0, 0, 3, 215.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [159]={next_id=160, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她迅速将盘子放到操作台上，然后低下头，双手撑着台面边缘，白色的发丝垂落，遮住了大半张脸。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT301_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4509", 0, 0, 3, 215.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
